$query = new WP_Query([
    'post_type'      => 'attachment',
    'post_status'    => 'inherit',
    'posts_per_page' => -1,
    'meta_query'     => [
        [
            'key'     => '_bns_is_gallery_item',
            'value'   => '1',
            'compare' => '=',
        ],
    ],
]);

if ($query->have_posts()) {
    while ($query->have_posts()) {
        $query->the_post();
        $id = get_the_ID();
        $file = get_attached_file($id);
        $basename = basename($file);
        
        if (isset($mappings[$basename])) {
            $cat = $mappings[$basename]['cat'];
            $title = $mappings[$basename]['title'];
            update_post_meta($id, '_bns_gallery_category_slug', $cat);
            wp_set_object_terms($id, [$cat], 'bns_gallery_category', false);
            wp_update_post([
                'ID'         => $id,
                'post_title' => $title,
            ]);
        }
    }
    wp_reset_postdata();
}

$categories = ShishaRent_Gallery::get_gallery_categories();
echo "Updated Dynamic Category Counts:\n";
foreach ($categories as $slug => $c) {
    echo "  - {$slug} ({$c['name']}): {$c['count']} items\n";
}
